def rle(s: str) -> str:
    """See SPEC.md."""
    result = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        result.append(s[i] + str(j - i))
        i = j
    return "".join(result)

